  if (t.includes('contact')) return 'Контактная форма сайта';
  return tool || 'Сайт FINMENTOR';
}

function statusLabel(value) {
  const v = String(value || '').toUpperCase();
  if (v === 'HOT') return 'HOT — ответить сегодня';
  if (v === 'WARM') return 'WARM — назначить Financial Health Check';
  if (v === 'COLD') return 'COLD — nurturing / позже';
