}

function cut(value, max = 320) {
  const text = safe(value);
  if (!text) return '—';
  if (text.length <= max) return text;
  return text.slice(0, max).trim() + '...';
}

function bullets(value, maxLines = 4, maxChars = 480) {
  const text = String(value || '').trim();
  if (!text) return '—';
  const lines = text.split('\n').map(v => safe(v)).filter(Boolean).slice(0, maxLines);
  if (!lines.length) return '—';
  const out = lines.map(v => `• ${v.replace(/^[-•]\s*/, '')}`).join('\n');
  return out.length > maxChars ? out.slice(0, maxChars).trim() + '...' : out;
}

